import re

def answer(question):
    if not isinstance(question, str):
        raise ValueError("syntax error")

    question = question.strip()
    if not question.startswith("What is ") or not question.endswith("?"):
        raise ValueError("unknown operation")

    expr = question[8:-1].strip()  # remove "What is " and trailing "?"
    if expr == "":
        raise ValueError("syntax error")

    # Normalize multi-word operators to single tokens
    expr = expr.replace("multiplied by", "multiplied_by")
    expr = expr.replace("divided by", "divided_by")

    tokens = expr.split()
    if not tokens:
        raise ValueError("syntax error")

    number_re = re.compile(r"^-?\d+$")
    allowed_ops = {"plus", "minus", "multiplied_by", "divided_by"}

    # If any token is neither a number nor an allowed operation, it's an unknown operation.
    for t in tokens:
        if number_re.match(t):
            continue
        if t in allowed_ops:
            continue
        # token is not a number and not a known operation
        raise ValueError("unknown operation")

    # Tokens must alternate: number (op number)*
    if len(tokens) % 2 == 0:
        # even number of tokens => ends or starts with operator -> syntax error
        raise ValueError("syntax error")

    # First token must be a number
    if not number_re.match(tokens[0]):
        raise ValueError("syntax error")

    try:
        result = int(tokens[0])
    except Exception:
        raise ValueError("syntax error")

    i = 1
    while i < len(tokens):
        op = tokens[i]
        num_token = tokens[i + 1]
        if not number_re.match(num_token):
            raise ValueError("syntax error")
        num = int(num_token)

        if op == "plus":
            result = result + num
        elif op == "minus":
            result = result - num
        elif op == "multiplied_by":
            result = result * num
        elif op == "divided_by":
            # use truncating division toward zero to match int behavior
            try:
                result = int(result / num)
            except ZeroDivisionError:
                raise ValueError("syntax error")
        else:
            # Shouldn't happen because of earlier check, but keep for safety
            raise ValueError("unknown operation")

        i += 2

    return result
